import React, { useEffect, useState } from 'react';

export default function AchievementsPanel({ token, me = {}, role = 'user', onViewNgo, setMsg, achievements: propAchievements }) {
  // Use propAchievements if available, otherwise initialize state for fetching
  const [achievements, setAchievements] = useState(propAchievements || null);
  const [badges, setBadges] = useState(propAchievements?.badges || []);

  useEffect(() => {
    // If badges are passed via prop, do not fetch from the API
    if (propAchievements) {
      setAchievements(propAchievements);
      setBadges(propAchievements.badges || []);
      return;
    }

    if (!token) return;

    const apiBase = process.env.REACT_APP_API || 'http://localhost:4000';
    const achievementUrl = role === 'NGO' ? `${apiBase}/api/ngo/achievements` : `${apiBase}/api/actions/achievements`;
    const userBadgesUrl = `${apiBase}/api/actions/user-badges`;

    // FIX: Use Promise.all to fetch both lists and merge them to avoid one overwriting the other.
    Promise.all([
      fetch(achievementUrl, { headers: { Authorization: `Bearer ${token}` } }).then(r => r.json()),
      fetch(userBadgesUrl, { headers: { Authorization: `Bearer ${token}` } }).then(r => r.json())
    ])
    .then(([achievementsData, userBadgesData]) => {
      setAchievements(achievementsData);

      // Collect all badges from both responses
      const allBadges = [
        ...(achievementsData?.badges || []),
        ...(userBadgesData?.badges || [])
      ];

      // Deduplicate badges using a Set to ensure unique badge keys/titles
      const uniqueBadgesMap = {};
      allBadges.forEach(badge => {
        // Use a combination of key properties for uniqueness
        const key = badge.badge_key || badge.title || badge.id; 
        if (key) {
          uniqueBadgesMap[key] = badge;
        }
      });
      
      setBadges(Object.values(uniqueBadgesMap));
    })
    .catch(err => { 
      console.error('Achievements load error', err); 
      setAchievements({ badges: [] }); 
      setBadges([]);
    });

  }, [token, role, propAchievements]); // Added propAchievements as a dependency

  return (
    <div style={{ width: 320, flexShrink: 0 }}>
      <h3 style={{ marginBottom: 12 }}>Achievements</h3>

      <div style={{
        background: 'linear-gradient(135deg,#0ea5e9,#6366f1)',
        padding: 18,
        borderRadius: 12,
        color: '#fff',
        textAlign: 'center',
        boxShadow: '0 8px 30px rgba(2,6,23,0.08)'
      }}>
        <div style={{ fontSize: 42, fontWeight: 800 }}>{me?.points || 0}</div>
        <div style={{ opacity: 0.9, marginTop: 6 }}>POINTS</div>
      </div>

      <div style={{ marginTop: 14 }}>
        <h4 style={{ marginBottom: 8 }}>Badges</h4>

        {!achievements && (
          <div style={{ fontSize: 13, color: '#666' }}>Loading badges...</div>
        )}

        {achievements && badges.length === 0 && (
          <div style={{ padding: 14, borderRadius: 10, background: '#fff', color: '#666', boxShadow: '0 6px 20px rgba(0,0,0,0.04)' }}>No badges yet — participate to earn rewards.</div>
        )}

        {badges.length > 0 && (
  <div
    style={{
      display: "grid",
      gridTemplateColumns: "repeat(2,1fr)",
      gap: 10,
      marginTop: 10,
    }}
  >
    {badges.map((b, i) => {
      // Default icon mapping (does NOT affect backend logic)
      const iconMap = {
        "Gold Volunteer": "https://up.yimg.com/ib/th/id/OIP.M2jWfXFIT6yiFKdza-Xy9QHaHa?pid=Api&rs=1&c=1&qlt=95&w=121&h=121",
        "Silver Volunteer": "https://up.yimg.com/ib/th/id/OIP.8jVsS3Paqnphh1RUaZRO_gHaHa?pid=Api&rs=1&c=1&qlt=95&w=120&h=120",
        "Bronze Volunteer": "https://up.yimg.com/ib/th/id/OIP.OHs_yaTRMl1wF9glVaPZmgHaHa?pid=Api&rs=1&c=1&qlt=95&w=105&h=105",

        "Platinum Donor": "https://tse3.mm.bing.net/th/id/OIP.Imd7GlakFy5b_od5xomrDAHaHa?pid=Api&P=0&h=180",
        "Gold Donor": "https://up.yimg.com/ib/th/id/OIP.M2jWfXFIT6yiFKdza-Xy9QHaHa?pid=Api&rs=1&c=1&qlt=95&w=121&h=121",
        "Silver Donor": "https://up.yimg.com/ib/th/id/OIP.8jVsS3Paqnphh1RUaZRO_gHaHa?pid=Api&rs=1&c=1&qlt=95&w=120&h=120",
      };

      const finalIcon =
        b.icon || iconMap[b.title] || iconMap[b.badge_key] || "";

      return (
        <div
          key={b.badge_key || b.key || i}
          style={{
            background: "#fff",
            padding: 10,
            borderRadius: 10,
            boxShadow: "0 6px 18px rgba(0,0,0,0.06)",
            border: "1px solid #f1f5f9",
            textAlign: "center",
          }}
        >
          {finalIcon && (
            <img
              src={finalIcon}
              alt={b.title}
              style={{
                width: 45,
                height: 45,
                marginBottom: 6,
                objectFit: "contain",
              }}
            />
          )}

          <div style={{ fontWeight: 700, fontSize: 14 }}>
            {b.title || b.badge_key}
          </div>

          <div style={{ fontSize: 12, color: "#555" }}>
            {b.description || b.desc}
          </div>
        </div>
      );
    })}
  </div>
)}

      </div>

      {onViewNgo && (
        <div style={{ marginTop: 18 }}>
          <button onClick={() => onViewNgo()} style={{ width: '100%', padding: '10px 12px', borderRadius: 10, background: '#2563eb', color: '#fff', border: 0, cursor: 'pointer' }}>View Hosting NGOs</button>
        </div>
      )}
    </div>
  );
}
